c001.try_sql:
-- DUAL: one row, one column DUMMY
SELECT * FROM dual;
SELECT SYSDATE AS teraz FROM dual;

c003.try_sql:
-- The alias works in ORDER BY...
SELECT salary * 12 AS "Annual Pay" FROM employees ORDER BY "Annual Pay";
-- ...but not in WHERE (ORA-00904)
SELECT salary * 12 AS annual FROM employees WHERE annual > 100000;

c004.try_sql:
-- DISTINCT applies to the whole row: compare the row counts
SELECT DISTINCT department_id FROM employees;
SELECT DISTINCT department_id, job_title FROM employees ORDER BY 1, 2;

c100.try_sql:
-- Foreign key: department 99 is not in DEPARTMENTS -> ORA-02291
INSERT INTO employees (employee_id, last_name, hire_date, department_id)
VALUES (300, 'Test', SYSDATE, 99);

c104.try_sql:
-- Keywords and names: case does not matter; data: case matters
select LAST_NAME from EMPLOYEES where last_name = 'KING';
SELECT last_name AS "Name" FROM employees WHERE last_name = 'King';

c105.try_sql:
-- First *, then +: compare both columns
SELECT salary, salary + 100 * 12 AS bez_nawiasow, (salary + 100) * 12 AS z_nawiasami
FROM employees WHERE employee_id = 100;

c1050.try_sql:
-- A quoted alias may start with a digit...
SELECT salary AS "2024 pay" FROM employees;
-- ...an unquoted one may not
SELECT salary AS 2024_pay FROM employees;

c1051.try_sql:
-- ORDER BY salary is the alias (-e.salary), ORDER BY e.salary is the column
SELECT e.last_name, -e.salary AS salary FROM employees e ORDER BY salary;
SELECT e.last_name, -e.salary AS salary FROM employees e ORDER BY e.salary;

c1057.try_sql:
-- DATE + n and DATE - DATE work...
SELECT hire_date + 30 AS plus_30, SYSDATE - hire_date AS dni FROM employees;
-- ...DATE + DATE does not
SELECT hire_date + hire_date FROM employees;

c1058.try_sql:
-- NULL / 0 is simply NULL...
SELECT NULL / 0 AS wynik FROM dual;
-- ...while a number / 0 is an error
SELECT salary / 0 FROM employees;

c1060.try_sql:
-- A new pair (1001, 3) goes in, a repeated one (1001, 1) raises ORA-00001
INSERT INTO order_items (order_id, line_no, product_id, quantity, unit_price) VALUES (1001, 3, 11, 1, 10);
INSERT INTO order_items (order_id, line_no, product_id, quantity, unit_price) VALUES (1001, 1, 11, 1, 10);

c1061.try_sql:
-- A second NULL in a UNIQUE column (email) goes in...
INSERT INTO employees (employee_id, last_name, hire_date) VALUES (301, 'Nowy', SYSDATE);
SELECT employee_id, last_name, email FROM employees WHERE email IS NULL;
-- ...but a repeated value does not
INSERT INTO employees (employee_id, last_name, email, hire_date) VALUES (302, 'Kopia', 'SKING', SYSDATE);
